package com.taxhub.reporting.controller;

import com.taxhub.reporting.client.TaxEngineFeignClient;
import com.taxhub.reporting.dto.TaxFilingDto;
import com.taxhub.reporting.security.MerchantUserPrincipal;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/tax/filings")
public class TaxReportingProxyController {

    private final TaxEngineFeignClient taxEngineClient;

    public TaxReportingProxyController(TaxEngineFeignClient taxEngineClient) {
        this.taxEngineClient = taxEngineClient;
    }

    @GetMapping("/{filingId}")
    public ResponseEntity<TaxFilingDto> getTaxFilingDetails(
            @PathVariable Long filingId,
            @AuthenticationPrincipal MerchantUserPrincipal merchant) {
        // Force the verified merchantCode from security principal onto downstream Feign client
        TaxFilingDto filing = taxEngineClient.getHistoricalReturn(merchant.getMerchantCode(), filingId);
        return ResponseEntity.ok(filing);
    }
}
